var t=`0871-sajji`;var n=`world-0871`;var a=`PK`;var r=`south-asia`;var s=4;var o=304;var l={en:`Sajji`,ua:`Саджі`};var g={en:`Sajji is a Pakistan dish made with whole chicken, plain yogurt, lemon juice, ginger-garlic paste. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Саджі, страва кухні країни Пакистан. Основні складники: ціла курка, натуральний йогурт, лимонний сік, імбирно-часникова паста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var c=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 180 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 180 хвилин.`,t:[`marinating`],m:180,i:[[`whole-chicken`,1.6,`kg`],[`plain-yogurt`,230,`g`],[`lemon-juice`,60,`ml`],[`ginger-garlic-paste`,35,`g`],[`ground-coriander`,7,`g`],[`table-salt`,null,`to_taste`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 25 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 25 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`basmati-rice`,410,`g`],[`water`,720,`ml`]]},{en:`Roast the marinated whole chicken until juices run clear and an instant-read thermometer reaches 74°C in the thickest meat; rest before carving.`,ua:`Запікайте цілу мариновану курку до прозорого соку й температури 74°C у найтовстішій частині м’яса; перед нарізанням дайте відпочити.`,t:[`roasting`],m:95,i:[[`canola-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`lemon`,1,`pcs`]]}];var h={slug:t,id:n,country:`PK`,region:r,servings:4,minutes:304,title:l,text:g,steps:c};export{a as country,h as default,n as id,o as minutes,r as region,s as servings,t as slug,c as steps,g as text,l as title};